<script>
    import { onMount } from 'svelte';
    import Preferences from './Preferences.svelte';
    import { translator, hydratePreferences } from './preferences.js';
    import { Button, Modal, Spinner } from 'flowbite-svelte';
    import { BellOutline, BookOpenOutline, BookOpenReaderOutline, BuildingOutline, CalendarMonthOutline, CashOutline, ChartPieOutline, ClipboardCheckOutline, ClipboardListOutline, CogOutline, FileInvoiceOutline, HomeOutline, ReceiptOutline, UserGraduateOutline, UsersGroupOutline, WalletOutline } from 'flowbite-svelte-icons';

    let meta = $state(null), section = $state('overview'), rows = $state([]), total = $state(0), page = $state(1);
    let loading = $state(true), busy = $state(false), error = $state(''), message = $state(''), search = $state('');
    let menu = $state(false), editor = $state(false), draft = $state({}), editing = $state(null), errors = $state({});
    let guide = $state(false), step = $state(0), invite = $state(false), inviteUrl = $state(''), access = $state(false);
    let personToEdit = $state(null), selectedRoles = $state([]);
    let month = $state(''), unread = $state(0);
    let preferencesOpen = $state(false), preferences = $state({}), preferencePassword = $state('');
    let attendanceSheet = $state(false), attendanceRecords = $state([]), attendanceClass = $state('');
    let promotionOpen = $state(false), promotionClass = $state(''), promotionStudents = $state([]);
    let batchInvoiceOpen = $state(false), batchInvoice = $state({billing_month: '', amount: '', due_on: '', description: 'Monthly school fee', class_id: ''});
    let reconciliation = $state(null);
    let studentProfile = $state(null), studentProfileLoading = $state(false), studentProfileError = $state('');
    const fontOptions = ['Instrument Sans', 'Inter', 'Poppins', 'Nunito', 'DM Sans', 'Manrope', 'Lato', 'Merriweather', 'Noto Nastaliq Urdu', 'system-ui'];
    let effectiveRoles = $derived(meta?.user?.effective_roles ?? meta?.user?.roles ?? []);
    let definition = $derived(meta?.modules.find(m => m.key === section));
    function iconFor(key) {
        return ({overview: HomeOutline, people: UsersGroupOutline, notifications: BellOutline, audit: ChartPieOutline, settings: CogOutline, academic_years: CalendarMonthOutline, classes: BuildingOutline, subjects: BookOpenOutline, staff: UsersGroupOutline, students: UserGraduateOutline, guardian_links: UsersGroupOutline, teacher_assignments: BookOpenReaderOutline, attendance: ClipboardCheckOutline, timetables: CalendarMonthOutline, exams: ClipboardListOutline, grade_bands: ChartPieOutline, exam_subjects: BookOpenOutline, grades: ReceiptOutline, invoices: FileInvoiceOutline, payments: CashOutline, expenses: WalletOutline, leave_requests: CalendarMonthOutline, payroll: WalletOutline, payroll_payments: CashOutline, notices: BellOutline})[key] ?? ClipboardListOutline;
    }
    let title = $derived(definition?.label ?? ({overview: 'Your school, in one place', people: 'People & access', notifications: 'Notifications', invitations: 'Invitations', settings: 'School settings', audit: 'Activity history'}[section] ?? section));
    let pageHelp = $derived(definition && !definition.canWrite ? ({students:'View the students connected to your account. Contact your school if a student is missing.', attendance:'See recorded attendance for the students connected to your account.', grades:'Your school publishes reviewed results here. Draft results remain private.', invoices:'View your fee invoices and outstanding balances. Contact the school office to arrange payment.', payments:'View recorded payments and print your receipts.', timetables:'Check class times, subjects and rooms for your school week.', exams:'View the exams your school has shared with you.', notices:'Read the latest messages shared with your school community.'}[section] ?? definition.help) : definition?.help);
    let steps = $derived([
        {title: `Welcome to ${section === 'overview' ? 'your workspace' : title}`, body: pageHelp ?? 'Use the menu to open your school tools. You only see information your role is allowed to access.'},
        {title: 'Find what you need', body: definition ? 'Search by a name or reference. Each card shows a record. Use Previous and Next to move through the results.' : 'Start with academic years, then classes and subjects. Invite people and link their accounts to their school records.'},
        {title: 'Work with confidence', body: definition?.canWrite ? `Choose Add ${definition.singular} to create a record. Fields marked * are required. Save your changes before leaving the form.` : 'Your school administrator manages access and assignments. If your page is empty, ask them to link your account to the right student or class.'},
        {title: 'Help is always here', body: 'Open Page guide any time to replay these tips. On a phone, the Menu button opens all your tools. Account lets you change your password.'}
    ]);
    const csrf = document.querySelector('meta[name="csrf-token"]').content;
    let latestRequest = 0;
    async function api(path, method = 'GET', body) {
        const response = await fetch(path, {method, credentials: 'same-origin', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': csrf, ...(body instanceof FormData ? {} : {'Content-Type': 'application/json'})}, ...(body ? {body: body instanceof FormData ? body : JSON.stringify(body)} : {})});
        if ([401, 419].includes(response.status)) { location.assign('/login'); throw new Error('Your session ended. Please sign in again.'); }
        const contentType = response.headers.get('content-type') ?? '';
        if (!contentType.includes('application/json')) {
            const e = new Error(`The server returned an unexpected response (${response.status}). Please refresh and try again.`);
            e.status = response.status;
            throw e;
        }
        const data = await response.json();
        if (!response.ok) { const e = new Error(data.message ?? 'Unable to complete this action. Please try again.'); e.errors = data.errors ?? {}; throw e; }
        return data;
    }
    function applyBranding() {
        const settings = meta?.settings ?? {};
        document.documentElement.style.setProperty('--accent', settings.color_primary || '#725752');
        document.documentElement.style.setProperty('--glow', settings.color_secondary || '#b8dacf');
        document.body.style.fontFamily = `'${settings.font_family || 'Instrument Sans'}', sans-serif`;
    }
    async function refreshMeta() { meta = await api('/portal/meta'); hydratePreferences(meta.user.interface_preferences); applyBranding(); }
    async function switchContext(event) {
        const [schoolId, branchId] = event.currentTarget.value.split(':').map(Number);
        busy = true;
        try {
            await api('/portal/context', 'PUT', {school_id: schoolId, branch_id: branchId});
            section = 'overview';
            page = 1;
            await refreshMeta();
            await loadRows();
        } catch (e) {
            error = e.message;
        } finally {
            busy = false;
        }
    }
    async function loadRows() {
        const requestNumber = ++latestRequest;
        const activeDefinition = definition;
        const activeSection = section;
        loading = true; error = '';
        try {
            if (activeDefinition) { const requests = [api(`/portal/records/${activeSection}?page=${page}&search=${encodeURIComponent(search)}&month=${month}`)]; if (activeSection === 'payments' && activeDefinition.canWrite) requests.push(api(`/portal/payments/reconciliation${month ? `?month=${month}` : ''}`)); const [data, reconciliationData] = await Promise.all(requests); if (requestNumber !== latestRequest) return; rows = data.rows; total = data.total; reconciliation = reconciliationData ?? null; }
            else if (['people', 'audit', 'invitations', 'notifications'].includes(activeSection)) { const data = await api(`/portal/${activeSection === 'people' ? 'users' : activeSection}?page=${page}`); if (requestNumber !== latestRequest) return; const result = data.users ?? data.rows; rows = result.data; total = result.total; if (data.unread !== undefined) unread = data.unread; }
            else { rows = []; total = 0; reconciliation = null; }
        } catch (e) { if (requestNumber === latestRequest) error = e.message; } finally { if (requestNumber === latestRequest) loading = false; }
    }
    async function navigate(key) {
        section = key; page = 1; search = ''; month = ''; menu = false; message = ''; await loadRows();
        if (key === section && key !== 'audit' && !meta.user.tutorials?.includes(key)) { step = 0; guide = true; }
    }
    async function finishGuide() {
        const completedSection = section;
        guide = false;
        meta.user.tutorials = [...(meta.user.tutorials ?? []), completedSection];
        try { await api('/portal/tutorial', 'PUT', {module: completedSection}); } catch(e) { error = e.message; }
    }
    function openEditor(row = null) {
        editing = row?.id ?? null; errors = {}; draft = {};
        for (const field of definition.fields) {
            draft[field.name] = row ? (field.type === 'money' ? (row[field.name] / 100).toFixed(2) : row[field.name] ?? '') : (field.type === 'select' ? field.choices[0] : '');
        }
        editor = true;
    }
    async function saveRecord(event) {
        event.preventDefault(); busy = true; errors = {};
        try { const payload = section === 'submissions' ? new FormData(event.currentTarget) : draft; await api(`/portal/records/${section}${editing ? '/' + editing : ''}`, editing ? 'PUT' : 'POST', payload); editor = false; message = 'Record saved successfully.'; await refreshMeta(); await loadRows(); }
        catch(e) { errors = e.errors; errors.form = [e.message]; } finally { busy = false; }
    }
    async function openStudentProfile(student) {
        studentProfile = null; studentProfileError = ''; studentProfileLoading = true;
        try { studentProfile = await api(`/portal/students/${student.id}/360`); } catch (e) { studentProfileError = e.message; } finally { studentProfileLoading = false; }
    }
    function display(field, value) {
        if (value === null || value === '') return '—';
        if (field.type === 'relation') return meta.options[field.relation]?.find(o => String(o.value) === String(value))?.name ?? `#${value}`;
        if (field.type === 'money') return `${meta.settings.currency ?? ''} ${(value / 100).toFixed(2)}`;
        return String(value).replaceAll('_', ' ');
    }
    function overviewValue(stat) {
        if (stat.format === 'money') return `${meta.settings.currency ?? ''} ${(Number(stat.value) / 100).toLocaleString(undefined, {minimumFractionDigits: 0, maximumFractionDigits: 0})}`;
        return Number(stat.value).toLocaleString();
    }
    async function createInvite(event) {
        event.preventDefault(); busy = true; errors = {};
        try { const result = await api('/portal/invitations', 'POST', draft); inviteUrl = result.url; message = result.message; }
        catch(e) { errors = e.errors; errors.form = [e.message]; } finally { busy = false; }
    }
    async function updateAccess(person) {
        busy = true; error = '';
        try { const result = await api(`/portal/users/${person.id}`, 'PUT', {roles: person.roles, is_active: person.access_status !== 'active'}); message = result.message; await loadRows(); await refreshMeta(); } catch(e) { error = e.message; } finally { busy = false; }
    }
    async function revokeInvitation(invitation) {
        busy = true; error = '';
        try { const result = await api(`/portal/invitations/${invitation.id}`, 'DELETE'); message = result.message; await loadRows(); }
        catch(e) { error = e.message; } finally { busy = false; }
    }
    async function saveAccess(event) {
        event.preventDefault(); busy = true; errors = {};
        try { const result = await api(`/portal/users/${personToEdit.id}`, 'PUT', {roles:selectedRoles, is_active:personToEdit.is_active}); access = false; message = result.message; await loadRows(); await refreshMeta(); }
        catch(e) { errors.form = [Object.values(e.errors).flat().join(' ') || e.message]; } finally { busy = false; }
    }
    async function openAttendance() {
        errors = {}; busy = true;
        try {
            const students = await api(`/portal/attendance/roster?class_id=${attendanceClass}`);
            attendanceRecords = students.rows.map(s => ({student_id:s.id, name:s.name, status:''}));
            attendanceSheet = true;
        } catch(e) { error = e.message; } finally { busy = false; }
    }
    async function saveAttendance(event) {
        event.preventDefault(); busy = true; errors = {};
        try { const result = await api('/portal/attendance/batch','PUT',{records:attendanceRecords.filter(r => r.status).map(r => ({student_id:r.student_id,status:r.status}))}); attendanceSheet = false; message = result.message; await loadRows(); }
        catch(e) { errors.form = [Object.values(e.errors).flat().join(' ') || e.message]; } finally { busy = false; }
    }
    function openPromotion() { promotionClass = ''; promotionOpen = true; errors = {}; }
    async function savePromotion(event) {
        event.preventDefault(); busy = true; errors = {};
        try { const result = await api('/portal/promotions', 'POST', {student_ids: promotionStudents.map(Number), class_id: Number(promotionClass)}); promotionOpen = false; promotionStudents = []; message = result.message; await refreshMeta(); await loadRows(); }
        catch(e) { errors.form = [Object.values(e.errors ?? {}).flat().join(' ') || e.message]; } finally { busy = false; }
    }
    function openBatchInvoice() { batchInvoice = {billing_month: '', amount: '', due_on: '', description: 'Monthly school fee', class_id: ''}; errors = {}; batchInvoiceOpen = true; }
    async function saveBatchInvoice(event) {
        event.preventDefault(); busy = true; errors = {};
        try { const result = await api('/portal/invoices/batch', 'POST', batchInvoice); batchInvoiceOpen = false; message = result.message; await refreshMeta(); await loadRows(); }
        catch(e) { errors.form = [Object.values(e.errors ?? {}).flat().join(' ') || e.message]; } finally { busy = false; }
    }
    async function saveSettings(event) {
        event.preventDefault(); busy = true; error = '';
        try { const form = new FormData(event.currentTarget); await api('/portal/settings', 'POST', form); await refreshMeta(); message = 'School settings saved.'; } catch(e) { error = Object.values(e.errors).flat().join(' ') || e.message; } finally { busy = false; }
    }
    async function readNotification(row) {
        busy = true;
        try { await api(`/portal/notifications/${row.id}/read`, 'PUT'); await loadRows(); }
        catch(e) { error = e.message; } finally { busy = false; }
    }
    async function openPreferences() {
        errors = {}; busy = true; preferencePassword = '';
        try { preferences = await api('/portal/notification-preferences'); preferencesOpen = true; }
        catch(e) { error = e.message; } finally { busy = false; }
    }
    async function savePreferences(event) {
        event.preventDefault(); errors = {}; busy = true;
        try { const result = await api('/portal/notification-preferences', 'PUT', {whatsapp_phone:preferences.whatsapp_phone, whatsapp_enabled:preferences.whatsapp_enabled, email_enabled:preferences.email_enabled, current_password:preferencePassword}); preferencesOpen = false; preferencePassword = ''; message = result.message; }
        catch(e) { errors.form = [Object.values(e.errors).flat().join(' ') || e.message]; } finally { busy = false; }
    }
    async function refreshUnread() {
        if (document.hidden || !meta) return;
        try { const data = await api('/portal/notifications'); unread = data.unread; } catch(e) { /* The inbox offers a visible retry through Refresh. */ }
    }
    onMount(() => {
        (async () => { try { await refreshMeta(); await navigate('overview'); await refreshUnread(); } catch(e) { error = e.message; loading = false; } })();
        const timer = setInterval(refreshUnread, 60000);
        return () => clearInterval(timer);
    });
</script>

<svelte:head><title>{$translator(title)} {$translator("· School workspace")}</title></svelte:head>
<a class="skip" href="#main">{$translator("Skip to content")}</a>
{#if meta}
<div class="workspace">
    <aside class:expanded={menu}>
        <a class="brand" href="/dashboard">{#if meta.settings.logo_data}<img class="school-logo" src={meta.settings.logo_data} alt="">{:else}<span class="mark">{$translator("S")}</span>{/if}<span>{meta.settings.school_name || 'School System'}<small>{$translator("A little clarity, every day.")}</small></span></a>
        <nav aria-label={$translator("School tools")}>
            <button class:active={section === 'overview'} onclick={() => navigate('overview')}>{$translator("Overview")}</button>
            {#if meta.canManage}<button class:active={section === 'people'} onclick={() => navigate('people')}>{$translator("People & access")}</button>{/if}
            <button class:active={section === 'notifications'} onclick={() => navigate('notifications')}>{$translator("Notifications")} {unread ? `(${unread} unread)` : ''}</button>
            {#each meta.modules as item}<button class:active={section === item.key} data-cy={`nav-${item.key}`} onclick={() => navigate(item.key)}>{$translator(item.label)}</button>{/each}
            {#if meta.canManage}<button class:active={section === 'audit'} onclick={() => navigate('audit')}>{$translator("Activity history")}</button>{/if}
            {#if meta.canManage}<button class:active={section === 'settings'} onclick={() => navigate('settings')}>{$translator("School settings")}</button>{/if}
        </nav>
    </aside>
    <div class="content">
        <header><button class="mobile-toggle" aria-expanded={menu} onclick={() => menu = !menu}>{$translator("☰ Menu")}</button>{#if meta.contexts?.length > 1}<label class="context-switcher"><span>{$translator("Workspace")}</span><select value={`${meta.current_context.school_id}:${meta.current_context.branch_id}`} onchange={switchContext} disabled={busy}>{#each meta.contexts as context}<option value={`${context.school_id}:${context.branch_id}`}>{context.school_name} · {context.branch_name}</option>{/each}</select></label>{/if}<span class="role">{effectiveRoles.map(role => $translator(role)).join(' · ')}</span><Preferences /><div class="account"><a href="/account">{$translator("Account")}</a><form action="/logout" method="post"><input type="hidden" name="_token" value={csrf}><button>{$translator("Sign out")}</button></form></div></header>
        <main id="main">
            {#if meta.degraded}<div class="alert error" role="status">Some workspace data is temporarily unavailable. Your account and school records remain protected; refresh this page or contact the platform owner if this continues.</div>{/if}
            <div class="heading"><div><p class="eyebrow">{$translator("YOUR SCHOOL WORKSPACE")}</p><h1>{$translator(title)}</h1><p>{pageHelp ?? `Welcome, ${meta.user.name}. Let's make today a good school day.`}</p></div>{#if section !== 'audit'}<Button color="alternative" onclick={() => {step = 0; guide = true;}}>{$translator("Page guide")}</Button>{/if}</div>
            {#if error}<div class="alert error" role="alert">{$translator(error)}<button onclick={loadRows}>{$translator("Try again")}</button></div>{/if}
            {#if message}<div class="alert success" role="status">{$translator(message)}</div>{/if}
            {#if loading}<div class="empty"><div class="loading-scene" role="status"><div class="loading-orbit" aria-hidden="true">{$translator("S")}</div><p>{$translator("Loading your workspace…")}</p></div></div>
            {:else if section === 'overview'}
                <section class="welcome"><p class="eyebrow">{$translator("A CLEAR START")}</p><h2>{$translator("Everything you need.")}<br>{$translator("One calm workspace.")}</h2><p>{$translator("Choose a tool below to get started. Your information is shared according to your role and school assignments.")}</p>{#if meta.canManage}<Button onclick={() => navigate('people')}>{$translator("Invite your school team")}</Button>{/if}</section>
                <section class="overview-stats" aria-label={$translator("School summary")}>{#each meta.overview?.stats ?? [] as stat}{@const Icon = iconFor(stat.icon)}<article class="overview-stat" data-cy="overview-stat"><span class="stat-icon"><Icon size="20" ariaLabel="" /></span><div><p>{$translator(stat.label)}</p><strong>{overviewValue(stat)}</strong></div></article>{/each}</section>
                <section class="overview-panels"><article class="overview-panel attendance-panel"><div class="panel-heading"><div><p class="eyebrow">{$translator("TODAY")}</p><h2>{$translator("Attendance summary")}</h2></div><span class="panel-value">{meta.overview?.attendance?.percentage ?? 0}%</span></div><div class="progress-track"><span style={`width:${meta.overview?.attendance?.percentage ?? 0}%`}></span></div><p>{meta.overview?.attendance?.attended ?? 0} {$translator("attended")} {$translator("out of")} {meta.overview?.attendance?.total ?? 0} {$translator("recorded today")}</p></article><article class="overview-panel fees-panel"><div class="panel-heading"><div><p class="eyebrow">{$translator("FEE COLLECTION")}</p><h2>{$translator("Financial snapshot")}</h2></div><span class="panel-value">{meta.overview?.fees?.collection_rate ?? 0}%</span></div><div class="progress-track"><span style={`width:${meta.overview?.fees?.collection_rate ?? 0}%`}></span></div><div class="fee-summary"><span>{$translator("Collected")} <strong>{overviewValue({format: 'money', value: meta.overview?.fees?.collected ?? 0})}</strong></span><span>{$translator("Outstanding")} <strong>{overviewValue({format: 'money', value: meta.overview?.fees?.outstanding ?? 0})}</strong></span><span>{$translator("Overdue")} <strong>{overviewValue({format: 'money', value: meta.overview?.fees?.overdue ?? 0})}</strong></span></div><article class="overview-panel staff-attendance-panel"><div class="panel-heading"><div><p class="eyebrow">{$translator("STAFF TODAY")}</p><h2>{$translator("Staff attendance")}</h2></div><span class="panel-value">{meta.overview?.staff_attendance?.percentage ?? 0}%</span></div><div class="progress-track"><span style={`width:${meta.overview?.staff_attendance?.percentage ?? 0}%`}></span></div><div class="fee-summary"><span>{$translator("Present")} <strong>{meta.overview?.staff_attendance?.present ?? 0}</strong></span><span>{$translator("Late")} <strong>{meta.overview?.staff_attendance?.late ?? 0}</strong></span><span>{$translator("Absent")} <strong>{meta.overview?.staff_attendance?.absent ?? 0}</strong></span></div></article></article><article class="overview-panel profile-panel"><p class="eyebrow">{$translator("YOUR ACCOUNT")}</p><h2>{meta.user.name}</h2><p>{$translator("Signed in as")} {effectiveRoles.map(role => $translator(role)).join(' · ')}</p><div class="profile-chip"><span>{meta.user.name.slice(0, 1).toUpperCase()}</span><div><strong>{meta.settings.school_name || $translator('School System')}</strong><small>{$translator("Your school workspace")}</small></div></div></article></section>
                {#if meta.canManage}<div class="setup"><h2>{$translator("Set up your school in order")}</h2><p>{$translator("1. Add an academic year, classes and subjects. 2. Invite teachers, students and parents. 3. Create student records and link accounts. 4. Assign teachers and connect guardians. 5. Begin attendance, lessons and fees.")}</p></div>{/if}
                <div class="tiles">{#each meta.modules as item}{@const Icon = iconFor(item.key)}<button class="tile" onclick={() => navigate(item.key)}><span class="tile-icon"><Icon size="22" ariaLabel="" /></span><h2>{$translator(item.label)}</h2><p>{$translator(item.help)}</p><span class="open">{$translator("Open tool →")}</span></button>{/each}</div>
            {:else if definition}
                {#if ['invoices','payments','payroll','payroll_payments'].includes(section)}<div class="actions"><label for="billing-month">{$translator("Fee / salary month")}</label><input id="billing-month" type="month" bind:value={month}><Button color="alternative" onclick={() => {page = 1; loadRows();}}>{$translator("Show month")}</Button><Button color="alternative" onclick={() => {month = ''; page = 1; loadRows();}}>{$translator("All months")}</Button></div>{/if}
                {#if section === 'payments' && definition.canWrite && reconciliation}<section class="reconciliation" aria-label={$translator("Payment reconciliation")}><div class="panel-heading"><div><p class="eyebrow">{$translator("CASHBOOK CHECK")}</p><h2>{$translator("Payment reconciliation")}</h2></div><span class="panel-value">{reconciliation.receipts}</span></div><p>{$translator("Recorded receipts")}</p><div class="reconciliation-grid"><span>{$translator("Billed")} <strong>{overviewValue({format: 'money', value: reconciliation.billed})}</strong></span><span>{$translator("Collected")} <strong>{overviewValue({format: 'money', value: reconciliation.collected})}</strong></span><span>{$translator("Outstanding")} <strong>{overviewValue({format: 'money', value: reconciliation.outstanding})}</strong></span><span>{$translator("Open invoices")} <strong>{reconciliation.outstanding_invoices}</strong></span><span>{$translator("Overdue invoices")} <strong>{reconciliation.overdue_invoices}</strong></span></div><div class="method-list">{#each [['current','Current'],['1_30','1–30 days late'],['31_60','31–60 days late'],['61_plus','61+ days late']] as bucket}<span>{bucket[1]} <strong>{overviewValue({format: 'money', value: reconciliation.aging?.[bucket[0]] ?? 0})}</strong></span>{/each}{#each reconciliation.methods ?? [] as method}<span>{method.method.replaceAll('_', ' ')} <strong>{overviewValue({format: 'money', value: method.amount})}</strong> · {method.receipts} {$translator("receipts")}</span>{/each}{#if !reconciliation.methods?.length}<span>{$translator("No receipts recorded for this period.")}</span>{/if}</div><div class="actions"><a href={`/portal/payments/reconciliation/export${month ? `?month=${month}` : ''}`} download>{$translator("Download CSV statement")}</a></div></section>{/if}
                <div class="toolbar"><form onsubmit={(e) => {e.preventDefault(); page = 1; loadRows();}}><label class="sr-only" for="search">{$translator("Search records")}</label><input id="search" bind:value={search} placeholder={$translator("Search name or reference…")} maxlength="100"><Button type="submit" color="alternative">{$translator("Search")}</Button></form><div class="actions">{#if section === 'students' && definition.canWrite}<Button color="alternative" disabled={!promotionStudents.length} onclick={openPromotion}>{$translator("Promote selected")} ({promotionStudents.length})</Button>{/if}{#if section === 'invoices' && definition.canWrite}<Button color="alternative" onclick={openBatchInvoice}>{$translator("Create monthly invoices")}</Button>{/if}{#if definition.canWrite}<Button onclick={() => openEditor()} data-cy="add-record">{$translator("Add")} {definition.singular}</Button>{/if}</div></div>
                {#if section === 'attendance' && definition.canWrite}<div class="actions"><label for="attendance-class">{$translator("Class")}</label><select id="attendance-class" bind:value={attendanceClass}><option value="">{$translator("Choose a class")}</option>{#each meta.options.classes ?? [] as option}<option value={option.value}>{option.name}</option>{/each}</select><Button color="alternative" disabled={busy || !attendanceClass} onclick={openAttendance}>{$translator("Quick attendance")}</Button></div>{/if}<p class="count">{total} {total === 1 ? 'record' : 'records'}</p>
                {#if !rows.length}<div class="empty"><h2>{$translator("No records to show yet")}</h2><p>{definition.canWrite ? `Use Add ${definition.singular} to create the first record. Linked records such as classes must be created first.` : 'Your school will share records here once your account is linked and information is available.'}</p></div>{/if}
                <div class="records">{#each rows as row}<article class="record" data-cy="record">{#if section === 'students' && definition.canWrite}<label class="check"><input type="checkbox" value={row.id} bind:group={promotionStudents}>{$translator("Select for promotion")}</label>{/if}<h2>{row.name ?? row.title ?? row.reference ?? `${definition.singular} #${row.id}`}</h2><dl>{#each definition.fields as field}<div><dt>{$translator(field.label)}</dt><dd>{display(field, row[field.name])}</dd></div>{/each}{#if row.attachment_path}<div><dt>{$translator("Attachment")}</dt><dd><a href={`/portal/submissions/${row.id}/attachment`} target="_blank" rel="noopener">{row.attachment_name ?? $translator("Download file")}</a></dd></div>{/if}{#if row.payment_status}<div><dt>{$translator("Payment status")}</dt><dd>{display({type: 'money'}, row.paid)}</dd></div>{/if}{#if row.balance !== undefined}<div><dt>{$translator("Outstanding balance")}</dt><dd>{display({type: 'money'}, row.balance)}</dd></div>{/if}{#if row.net !== undefined}<div><dt>{$translator("Net pay")}</dt><dd>{display({type: 'money'}, row.net)}</dd></div>{/if}{#if row.percentage !== undefined}<div><dt>{$translator("Percentage")}</dt><dd>{row.percentage}%</dd></div>{/if}</dl><div class="actions">{#if section === 'students'}<Button color="alternative" onclick={() => openStudentProfile(row)}>{$translator("View 360 profile")}</Button>{/if}{#if section === 'grades' && effectiveRoles.some(role => ['owner','admin','parent','student'].includes(role))}<a href={`/report-cards/${row.exam_id}/${row.student_id}`} target="_blank" rel="noopener">{$translator("Full report card")}</a>{/if}{#if definition.canWrite && !definition.immutable}<Button color="alternative" onclick={() => openEditor(row)}>{$translator("Edit")}</Button>{/if}{#if ['payments','invoices','payroll','payroll_payments','grades'].includes(section)}<a href={`/reports/${section}/${row.id}`} target="_blank" rel="noopener">{$translator("Print / save PDF")}</a>{/if}</div></article>{/each}</div>
            {:else if section === 'notifications'}
                <div class="setup"><h2>{$translator("Your private school inbox")}</h2><p>{$translator("Find announcements, exam reminders and updates linked to your account. New messages appear as school changes are processed. WhatsApp and email delivery require the school to connect those services.")}</p></div>
                <Button color="alternative" onclick={loadRows}>{$translator("Refresh notifications")}</Button> <Button color="alternative" disabled={busy} onclick={openPreferences}>{$translator("Delivery preferences")}</Button>
                <p class="count">{unread} {$translator("unread")}</p>
                <div class="records">{#each rows as row}<article class="record" data-cy="notification"><h2>{row.title}</h2><p>{row.body}</p><p>{row.read_at ? 'Read' : 'Unread'}</p>{#each row.deliveries ?? [] as delivery}<p>{delivery.channel}: {({pending: 'Waiting to send', processing: 'Sending', accepted: 'Accepted by provider; delivery not yet confirmed', delivered: 'Delivered', read: 'Read by recipient', failed: 'Delivery failed', unknown: 'Delivery outcome unknown; contact school', skipped: 'Not sent because access or preferences changed'})[delivery.status] ?? delivery.status}</p>{/each}<div class="actions">{#if !row.read_at}<Button disabled={busy} color="alternative" onclick={() => readNotification(row)}>{$translator("Mark as read")}</Button>{/if}<Button color="alternative" onclick={() => navigate(row.module)}>{$translator("Open related records")}</Button></div></article>{/each}</div>
                {#if !rows.length}<p class="empty">{$translator("You're up to date. Your school notifications will appear here.")}</p>{/if}
            {:else if section === 'people'}
                <div class="setup"><h2>{$translator("Access starts with an invitation")}</h2><p>{$translator("Choose a person's role, share their private invitation link, then link their account to a student or teacher assignment. Parents only see students connected through Guardian links. Only the Owner can invite administrators.")}</p></div>
                <Button onclick={() => {draft = {name:'',email:'',roles:['teacher']}; errors = {}; inviteUrl = ''; invite = true;}}>{$translator("Invite person")}</Button> <Button color="alternative" onclick={() => navigate('invitations')}>{$translator("Manage invitations")}</Button>
                <div class="records people">{#each rows as person}<article class="record"><h2>{person.name}</h2><p>{person.username || person.email}</p><p>{person.roles?.join(' · ')} · {$translator(person.access_status === 'active' ? 'Branch access active' : 'Branch access suspended')} · {$translator(person.is_active ? 'Account active' : 'Account suspended')}</p>{#if person.id !== meta.user.id && !person.roles?.includes('owner') && (effectiveRoles.includes('owner') || !person.roles?.includes('admin'))}<Button color="alternative" onclick={() => {personToEdit = person; selectedRoles = [...person.roles]; errors = {}; access = true;}}>{$translator("Edit roles")}</Button> <Button color="alternative" disabled={busy} onclick={() => updateAccess(person)}>{$translator(person.access_status === 'active' ? 'Suspend branch access' : 'Restore branch access')}</Button>{/if}</article>{/each}</div>
            {:else if section === 'invitations'}
                <div class="setup"><h2>{$translator("Keep invitation links under your control")}</h2><p>{$translator("Revoke an unused link if it was shared with the wrong person. Expired or revoked links cannot create accounts. To send a new link, return to People & access and invite the same email again. Accepted accounts are managed in People & access.")}</p></div>
                <Button color="alternative" onclick={() => navigate('people')}>{$translator("Back to people")}</Button>
                <div class="records people">{#each rows as invitation}<article class="record" data-cy="invitation"><h2>{invitation.name}</h2><p>{invitation.email}</p><p>{invitation.roles.join(' · ')}</p><p>{invitation.is_pending ? 'Awaiting acceptance' : 'Expired or revoked'}</p>{#if invitation.is_pending}<Button color="alternative" disabled={busy} onclick={() => revokeInvitation(invitation)}>{$translator("Revoke invitation")}</Button>{/if}</article>{/each}</div>
                {#if !rows.length}<p class="empty">{$translator("No outstanding invitations.")}</p>{/if}
            {:else if section === 'settings'}
                <form class="settings record" onsubmit={saveSettings} enctype="multipart/form-data"><label for="school_name">{$translator("School name *")}</label><input id="school_name" name="school_name" value={meta.settings.school_name ?? ''} required maxlength="150"><label for="currency">{$translator("Currency code *")}</label><input id="currency" name="currency" value={meta.settings.currency ?? ''} placeholder={$translator("For example PKR")} pattern={'[A-Z]{3}'} required><label for="timezone">{$translator("Timezone *")}</label><input id="timezone" name="timezone" value={meta.settings.timezone ?? ''} placeholder={$translator("For example Asia/Karachi")} required><h2>{$translator("Monthly fee automation")}</h2><p>{$translator("Optional: the daily scheduler creates one invoice per active student for the current month. Leave the amount at zero to disable it.")}</p><label for="monthly_fee_amount">{$translator("Monthly fee amount")}</label><input id="monthly_fee_amount" name="monthly_fee_amount" type="number" min="0" step="0.01" value={((Number(meta.settings.monthly_fee_amount ?? 0)) / 100).toFixed(2)}><label for="monthly_fee_due_day">{$translator("Monthly due day (1-28)")}</label><input id="monthly_fee_due_day" name="monthly_fee_due_day" type="number" min="1" max="28" value={meta.settings.monthly_fee_due_day ?? 10}><label for="monthly_fee_description">{$translator("Monthly fee description")}</label><input id="monthly_fee_description" name="monthly_fee_description" maxlength="255" value={meta.settings.monthly_fee_description ?? ''}><h2>{$translator("Late fee automation")}</h2><p>{$translator("Optional: once an invoice passes its grace period, the daily school scheduler creates one separate late-fee invoice per original fee. Leave the amount at zero to disable it.")}</p><label for="late_fee_amount">{$translator("Late fee amount")}</label><input id="late_fee_amount" name="late_fee_amount" type="number" min="0" step="0.01" value={((Number(meta.settings.late_fee_amount ?? 0)) / 100).toFixed(2)}><label for="late_fee_grace_days">{$translator("Grace period after due date (days)")}</label><input id="late_fee_grace_days" name="late_fee_grace_days" type="number" min="0" max="90" value={meta.settings.late_fee_grace_days ?? 0}><h2>{$translator("Brand appearance")}</h2><div class="brand-colors"><label for="color_primary">{$translator("Primary color")}</label><input id="color_primary" name="color_primary" type="color" value={meta.settings.color_primary || '#725752'}><label for="color_secondary">{$translator("Secondary color")}</label><input id="color_secondary" name="color_secondary" type="color" value={meta.settings.color_secondary || '#b8dacf'}></div><label for="font_family">{$translator("Typography")}</label><select id="font_family" name="font_family" value={meta.settings.font_family || 'Instrument Sans'}>{#each fontOptions as font}<option value={font}>{font}</option>{/each}</select><label for="logo">{$translator("School logo")}</label><input id="logo" name="logo" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"><p>{$translator("Upload a logo up to 1 MB. It appears in the school identity area.")}</p>{#if meta.settings.logo_data}<img class="school-logo-preview" src={meta.settings.logo_data} alt={$translator("Current school logo")}>{/if}<p>{$translator("These settings identify your school. Payment entries record payments received outside this application.")}</p><Button type="submit" disabled={busy}>{$translator("Save settings")}</Button></form>
            {:else if section === 'audit'}<div class="records">{#each rows as row}<article class="record"><h2>{row.action.replaceAll('_',' ')}</h2><p>{row.name ?? 'Former account'} · {row.module.replaceAll('_',' ')} #{row.record_id}</p><p>{row.created_at}</p></article>{/each}</div>{/if}
            {#if total > (definition ? 20 : 30)}<div class="pagination"><Button color="alternative" disabled={page === 1 || loading} onclick={() => {page--; loadRows();}}>{$translator("Previous")}</Button><span>{$translator("Page")} {page}</span><Button color="alternative" disabled={page * (definition ? 20 : 30) >= total || loading} onclick={() => {page++; loadRows();}}>{$translator("Next")}</Button></div>{/if}
        </main><footer>{$translator("School System · Built around your school day")}</footer>
    </div>
</div>
<Modal bind:open={guide} title={$translator(steps[step].title)} size="md" dismissable={false}><p class="guide-step">{$translator("STEP")} {step + 1} {$translator("OF")} {steps.length}</p><p class="guide-copy">{$translator(steps[step].body)}</p><div class="actions"><Button color="alternative" onclick={finishGuide}>{$translator("Skip guide")}</Button>{#if step > 0}<Button color="alternative" onclick={() => step--}>{$translator("Back")}</Button>{/if}<Button onclick={() => step < steps.length - 1 ? step++ : finishGuide()}>{$translator(step < steps.length - 1 ? 'Next tip' : 'Got it')}</Button></div></Modal>
<Modal bind:open={preferencesOpen} title={$translator("Notification delivery")}><form class="record-form" onsubmit={savePreferences}><p>{$translator("Your account inbox is always available. Enable extra channels only for contact details you own. You can turn them off at any time.")}</p>{#if errors.form}<p class="error" role="alert">{errors.form[0]}</p>{/if}<p>{$translator("WhatsApp:")} {preferences.whatsapp_ready ? 'Connected by school' : 'Not connected by school yet'}</p><label for="whatsapp-phone">{$translator("Your WhatsApp number, including country code")}</label><input id="whatsapp-phone" type="tel" placeholder="+12025550123" bind:value={preferences.whatsapp_phone}><label class="check"><input id="whatsapp-opt-in" type="checkbox" bind:checked={preferences.whatsapp_enabled}>{$translator("I agree to receive school updates on my WhatsApp number.")}</label><p>{$translator("Email:")} {preferences.email || 'No email linked'} · {preferences.email_ready ? 'Connected by school' : 'Not connected by school yet'}</p><label class="check"><input id="email-opt-in" type="checkbox" bind:checked={preferences.email_enabled} disabled={!preferences.email}>{$translator("Send school updates to my account email.")}</label><label for="preference-password">{$translator("Confirm your current password")}</label><input id="preference-password" type="password" autocomplete="current-password" bind:value={preferencePassword} required><p>{$translator("Only new notifications after you opt in are eligible. Pending messages may take a few minutes. Delivery depends on the connected service.")}</p><Button type="submit" disabled={busy}>{$translator("Save delivery preferences")}</Button></form></Modal>
<Modal bind:open={studentProfile} title={$translator("Student 360 profile")} size="lg">
    {#if studentProfileLoading}<div class="empty"><p>{$translator("Loading profile…")}</p></div>{:else if studentProfileError}<p class="error">{studentProfileError}</p>{:else if studentProfile}<section class="profile-grid"><article class="record"><h2>{studentProfile.student.name}</h2><p>{studentProfile.student.class_name} · {studentProfile.student.academic_year}</p><p>{$translator("Admission number")}: {studentProfile.student.admission_number}</p><p>{$translator("Status")}: {studentProfile.student.status}</p></article><article class="record"><h2>{$translator("Attendance")}</h2><p>{$translator("Recorded")}: {studentProfile.attendance?.recorded ?? 0}</p><p>{$translator("Attended")}: {studentProfile.attendance?.attended ?? 0}</p><p>{$translator("Absent")}: {studentProfile.attendance?.absent ?? 0}</p></article><article class="record"><h2>{$translator("Guardians")}</h2>{#each studentProfile.guardians ?? [] as guardian}<p>{guardian.name} · {guardian.relationship}</p>{/each}{#if !studentProfile.guardians?.length}<p>{$translator("No linked guardians")}</p>{/if}</article><article class="record"><h2>{$translator("Fees")}</h2><p>{$translator("Billed")}: {overviewValue({format: 'money', value: studentProfile.fee_summary?.billed ?? 0})}</p><p>{$translator("Paid")}: {overviewValue({format: 'money', value: studentProfile.fee_summary?.paid ?? 0})}</p><p>{$translator("Outstanding")}: {overviewValue({format: 'money', value: studentProfile.fee_summary?.outstanding ?? 0})}</p>{#each studentProfile.fees ?? [] as fee}<p>{fee.billing_month ?? fee.reference}: {overviewValue({format: 'money', value: fee.balance})} {$translator("outstanding")}</p>{#each fee.payments ?? [] as payment}<small>{payment.reference} · {payment.paid_on} · {overviewValue({format: 'money', value: payment.amount})}</small>{/each}{/each}{#if !studentProfile.fees?.length}<p>{$translator("No invoices")}</p>{/if}</article><article class="record"><h2>{$translator("Results")}</h2>{#each studentProfile.grades ?? [] as grade}<p>{grade.exam} · {grade.subject}: {grade.percentage}%</p>{/each}{#if !studentProfile.grades?.length}<p>{$translator("No published results")}</p>{/if}</article><article class="record"><h2>{$translator("Assignments")}</h2>{#each studentProfile.assignments ?? [] as assignment}<p>{assignment.title} · {assignment.due_on}</p>{/each}{#if !studentProfile.assignments?.length}<p>{$translator("No assignments")}</p>{/if}</article>{#if studentProfile.welfare}<article class="record"><h2>{$translator("Private welfare")}</h2>{#each studentProfile.welfare as welfare}<p>{welfare.record_date} · {welfare.record_type}: {welfare.details}</p>{/each}</article>{/if}</section>{/if}
</Modal>
<Modal bind:open={editor} title={`${editing ? 'Edit' : 'Add'} ${definition?.singular ?? 'record'}`} size="lg">
    <form onsubmit={saveRecord} class="record-form">{#if errors.form}<p role="alert" class="error">{errors.form[0]}</p>{/if}{#each definition?.fields ?? [] as field}<div class="field"><label for={`field-${field.name}`}>{$translator(field.label)}{field.optional ? ' (optional)' : ' *'}</label>{#if field.type === 'relation' || field.type === 'select'}<select name={field.name} id={`field-${field.name}`} bind:value={draft[field.name]} required={!field.optional}><option value="">{$translator("Choose")} {$translator(field.label)}</option>{#each field.type === 'relation' ? (meta.options[field.relation] ?? []) : field.choices.map(v => ({value:v,name:v.replaceAll('_',' ')})) as option}<option value={option.value}>{field.type === 'select' ? $translator(option.name) : option.name}</option>{/each}</select>{:else if field.type === 'textarea'}<textarea name={field.name} id={`field-${field.name}`} bind:value={draft[field.name]} required={!field.optional} maxlength="5000" rows="3"></textarea>{:else}<input name={field.name} id={`field-${field.name}`} type={['date','time','month','number'].includes(field.type) ? field.type : 'text'} inputmode={['money','decimal'].includes(field.type) ? 'decimal' : undefined} bind:value={draft[field.name]} required={!field.optional} min={field.min} max={field.max} maxlength="255">{/if}{#if errors[field.name]}<p class="error" role="alert">{errors[field.name][0]}</p>{/if}</div>{/each}{#if section === 'submissions'}<div class="field"><label for="submission-attachment">{$translator("Private attachment (optional)")}</label><input name="attachment" id="submission-attachment" type="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"/><small>{$translator("PDF, Word or image up to 10 MB. Only permitted school users can download it.")}</small></div>{/if}<div class="actions"><Button color="alternative" onclick={() => editor = false} disabled={busy}>{$translator("Cancel")}</Button><Button type="submit" disabled={busy}>{$translator(busy ? 'Saving…' : 'Save record')}</Button></div></form>
</Modal>
<Modal bind:open={attendanceSheet} title={$translator("Today's attendance")} size="lg"><form class="record-form" onsubmit={saveAttendance}><p>{meta.today} {$translator("· Choose a status for each student you want to record. Unselected students stay unchanged. Existing attendance for today will be updated.")}</p>{#if errors.form}<p class="error" role="alert">{errors.form[0]}</p>{/if}{#each attendanceRecords as record}<label for={`attendance-${record.student_id}`}>{record.name}</label><select id={`attendance-${record.student_id}`} bind:value={record.status}><option value="">{$translator("Leave unchanged")}</option><option value="present">{$translator("Present")}</option><option value="absent">{$translator("Absent")}</option><option value="late">{$translator("Late")}</option><option value="excused">{$translator("Excused")}</option></select>{/each}<Button type="submit" disabled={busy || !attendanceRecords.some(r => r.status)}>{$translator("Save attendance")}</Button></form></Modal><Modal bind:open={access} title={$translator("Edit account roles")}><form class="record-form" onsubmit={saveAccess}><p>{$translator("Update access for")} {personToEdit?.name}{$translator(". Verify their identity before assigning roles. Existing sessions will be revoked when you save.")}</p>{#if errors.form}<p class="error" role="alert">{errors.form[0]}</p>{/if}<fieldset><legend>{$translator("Roles")}</legend>{#each ['teacher','parent','student','accountant', ...(effectiveRoles.includes('owner') ? ['admin'] : [])] as role}<label class="check"><input type="checkbox" value={role} bind:group={selectedRoles}>{$translator(role)}</label>{/each}</fieldset><Button type="submit" disabled={busy}>{$translator("Save roles")}</Button></form></Modal><Modal bind:open={invite} title={$translator("Invite a person")}><form class="record-form" onsubmit={createInvite}>{#if errors.form}<p role="alert" class="error">{Object.values(errors).flat().join(' ')}</p>{/if}{#if inviteUrl}<p>{$translator("Share this private link directly with the invited person. It expires in 48 hours and can be used once.")}</p><label for="invitation-link">{$translator("Invitation link")}</label><input id="invitation-link" readonly value={inviteUrl} onclick={(e) => e.target.select()}>{:else}<label for="invite-name">{$translator("Full name *")}</label><input id="invite-name" bind:value={draft.name} required><label for="invite-email">{$translator("Email *")}</label><input id="invite-email" type="email" bind:value={draft.email} required><fieldset><legend>{$translator("Roles *")}</legend>{#each ['teacher','parent','student','accountant', ...(effectiveRoles.includes('owner') ? ['admin'] : [])] as role}<label class="check"><input type="checkbox" value={role} bind:group={draft.roles}>{$translator(role)}</label>{/each}</fieldset><Button type="submit" disabled={busy}>{$translator("Create private invitation")}</Button>{/if}</form></Modal>
<Modal bind:open={promotionOpen} title={$translator("Promote students")}><form class="record-form" onsubmit={savePromotion}><p>{$translator("Move the selected active students to a new class. Their previous enrollment remains in the academic history.")}</p>{#if errors.form}<p class="error" role="alert">{errors.form[0]}</p>{/if}<p><strong>{promotionStudents.length}</strong> {$translator("students selected")}</p><label for="promotion-class">{$translator("Target class *")}</label><select id="promotion-class" bind:value={promotionClass} required><option value="">{$translator("Choose a class")}</option>{#each meta.options.classes ?? [] as option}<option value={option.value}>{option.name}</option>{/each}</select><Button type="submit" disabled={busy || !promotionStudents.length}>{$translator(busy ? 'Promoting…' : 'Confirm promotion')}</Button></form></Modal>
<Modal bind:open={batchInvoiceOpen} title={$translator("Create monthly invoices")}><form class="record-form" onsubmit={saveBatchInvoice}><p>{$translator("Create one fee invoice for every active student, or choose one class. Existing invoices for the same month are skipped safely.")}</p>{#if errors.form}<p class="error" role="alert">{errors.form[0]}</p>{/if}<label for="invoice-month">{$translator("Fee month *")}</label><input id="invoice-month" type="month" bind:value={batchInvoice.billing_month} required><label for="invoice-amount">{$translator("Amount *")}</label><input id="invoice-amount" type="number" min="0.01" step="0.01" bind:value={batchInvoice.amount} required><label for="invoice-due">{$translator("Due date *")}</label><input id="invoice-due" type="date" bind:value={batchInvoice.due_on} required><label for="invoice-description">{$translator("Description *")}</label><input id="invoice-description" bind:value={batchInvoice.description} maxlength="255" required><label for="invoice-class">{$translator("Class (optional)")}</label><select id="invoice-class" bind:value={batchInvoice.class_id}><option value="">{$translator("All active students")}</option>{#each meta.options.classes ?? [] as option}<option value={option.value}>{option.name}</option>{/each}</select><Button type="submit" disabled={busy}>{$translator(busy ? 'Creating invoices…' : 'Create invoices')}</Button></form></Modal>
{:else}<main class="empty">{#if error}<p role="alert">{$translator(error)}</p><a href="/dashboard">{$translator("Reload workspace")}</a>{:else}<div class="loading-scene" role="status"><div class="loading-orbit" aria-hidden="true">{$translator("S")}</div><p>{$translator("Opening your school workspace…")}</p></div>{/if}</main>{/if}

<style>
